import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for a negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  it("rejects negative percent", () => {
    expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects percent > 100", () => {
    expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
  });

  it("rejects NaN", () => {
    expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
  });

  it("rejects Infinity", () => {
    expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
  });

  it("accepts 0%", () => {
    const p = new PercentageDiscountPolicy(0);
    expect(p.computeDiscountCents(10000)).toBe(0);
  });

  it("accepts 100%", () => {
    const p = new PercentageDiscountPolicy(100);
    expect(p.computeDiscountCents(10000)).toBe(10000);
  });

  it("computes 10% of 10000 = 1000", () => {
    const p = new PercentageDiscountPolicy(10);
    expect(p.computeDiscountCents(10000)).toBe(1000);
  });

  it("rounds down to nearest cent", () => {
    const p = new PercentageDiscountPolicy(33);
    // 33% of 100 = 33.0 exact
    expect(p.computeDiscountCents(100)).toBe(33);
    // 33% of 101 = 33.33 → floor = 33
    expect(p.computeDiscountCents(101)).toBe(33);
  });

  it("returns 0 for zero subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for negative subtotal", () => {
    const p = new PercentageDiscountPolicy(50);
    expect(p.computeDiscountCents(-1000)).toBe(0);
  });

  it("handles very large subtotal", () => {
    const p = new PercentageDiscountPolicy(15);
    expect(p.computeDiscountCents(999_999_99)).toBe(Math.floor(999_999_99 * 15 / 100));
  });
});

describe("FixedAmountDiscountPolicy", () => {
  it("rejects negative amount", () => {
    expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
  });

  it("rejects non-integer amount", () => {
    expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
  });

  it("accepts 0", () => {
    const p = new FixedAmountDiscountPolicy(0);
    expect(p.computeDiscountCents(5000)).toBe(0);
  });

  it("returns the fixed amount when subtotal exceeds it", () => {
    const p = new FixedAmountDiscountPolicy(500);
