describe("Cart — pricing pipeline", () => {
  it("computes subtotal correctly", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    cart.add(mkProduct("b", 500), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3500);
  });

  it("empty cart has all zeros", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t.subtotalCents).toBe(0);
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(0);
  });

  it("applies discount, then tax on the discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.10 }),
      region: "US",
    });
    cart.add(mkProduct("a", 10000), 1);
    const t = cart.totals();
    // subtotal = 10000, discount 10% = 1000, discounted = 9000
    // tax 10% of 9000 = 900
    expect(t.subtotalCents).toBe(10000);
    expect(t.discountCents).toBe(1000);
    expect(t.taxCents).toBe(900);
    expect(t.totalCents).toBe(9000 + 900);
  });

  it("shipping is computed against the discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(5000),
      shippingCalculator: new FlatShippingCalculator(500, 6000),
    });
    cart.add(mkProduct("a", 10000), 1);
    const t = cart.totals();
    // subtotal 10000, discount 5000, discounted = 5000
    // 5000 < 6000 threshold → shipping = 500
    expect(t.shippingCents).toBe(500);
  });

  it("shipping is free when discounted subtotal meets freeOver threshold", () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      shippingCalculator: new FlatShippingCalculator(500, 6000),
    });
    cart.add(mkProduct("a", 6000), 1);
    const t = cart.totals();
    expect(t.shippingCents).toBe(0);
  });

  it("discount is clamped to [0, subtotal]", () => {
    // Policy that tries to return more than subtotal
    const bigDiscount = { computeDiscountCents: () => 999999 };
    const cart = new Cart({ discountPolicy: bigDiscount });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1000);
    expect(t.totalCents).toBe(0);
  });

  it("negative discount from policy is clamped to 0", () => {
    const negativeDiscount = { computeDiscountCents: () => -500 };
    const cart = new Cart({ discountPolicy: negativeDiscount });
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });

  it("negative tax from calculator is clamped to 0", () => {
    const negativeTax = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negativeTax });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const negativeShipping = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negativeShipping });
    cart.add(mkProduct("a", 1000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.05 }),
      shippingCalculator: new FlatShippingCalculator(300),
      region: "US",
    });
    cart.add(mkProduct("a", 5000), 2);
    const t = cart.totals();
    // subtotal = 10000, discount 20% = 2000, discounted = 8000
    // tax 5% of 8000 = 400, shipping = 300
    // total = 8000 + 400 + 300 = 8700
    expect(t.totalCents).toBe(8700);
  });

  it("uses defaults (no discount, no tax, free shipping, US region)", () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1000);
  });
});

describe("Cart — checkout()", () => {
