    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(5);
      expect(ie.available).toBe(2);
    }
  });

  it("throws InventoryError on partial-stock denial (available < requested)", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (err) {
      expect(err).toBeInstanceOf(InventoryError);
      const ie = err as InventoryError;
      expect(ie.productId).toBe("a");
      expect(ie.requested).toBe(10);
      expect(ie.available).toBe(3);
    }
  });

  it("passes inventory check when available is true and quantity sufficient", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 10,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("passes inventory when availableQuantity is omitted and available is true", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2000);
  });

  it("uses asyncTaxProvider for tax computation", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      region: "US-CA",
    });
    cart.add(mkProduct("a", 10000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.0875),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // subtotal = 10000, discount 10% = 1000, discounted = 9000
    // tax 8.75% of 9000 = 787.5 → floor = 787
    expect(result.totals.taxCents).toBe(787);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US-CA");
  });

  it("combines priceFetcher + inventoryChecker + asyncTaxProvider", async () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US",
    });
    cart.add(mkProduct("a", 1000), 2);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(1200),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true, availableQuantity: 100 }),
    };
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.10),
    };
    const result = await cart.checkout({
      priceFetcher,
      inventoryChecker,
      asyncTaxProvider,
    });
    // refreshed subtotal = 1200 * 2 = 2400
    // discount = 200, discounted = 2200
    // tax = 10% of 2200 = 220
    // shipping = 500
    // total = 2200 + 220 + 500 = 2920
    expect(result.totals.subtotalCents).toBe(2400);
    expect(result.totals.discountCents).toBe(200);
    expect(result.totals.taxCents).toBe(220);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(2920);
  });

  it("propagates priceFetcher rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockRejectedValue(new Error("price service down")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow("price service down");
  });

  it("propagates asyncTaxProvider rejection", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("tax service error")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow("tax service error");
  });

  it("checkout without collaborators uses sync pipeline defaults", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(50),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.10 }),
      shippingCalculator: new FreeShippingCalculator(),
      region: "US",
    });
    cart.add(mkProduct("a", 2000), 1);
    const result = await cart.checkout();
    // subtotal 2000, discount 50% = 1000, discounted = 1000
    // tax 10% of 1000 = 100
    // total = 1000 + 100 = 1100
    expect(result.totals.totalCents).toBe(1100);
  });

  it("first inventory denial wins for multiple lines", async () => {
    const cart = new Cart();
    cart.add(mkProduct("a", 1000), 1);
    cart.add(mkProduct("b", 2000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn()
