toolArgs.file_text:
import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const line = (
  id: string,
  unitPriceCents: number,
  quantity: number,
  weightGrams?: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  it("rejects negative flatCents", () => {
    expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
  });

  it("rejects non-integer flatCents", () => {
    expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
  });

  it("rejects negative freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
  });

  it("rejects non-integer freeOverCents", () => {
    expect(() => new FlatShippingCalculator(500, 10.5)).toThrow(RangeError);
  });

  it("returns flat fee for non-empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([line("a", 1000, 1)], 1000)).toBe(599);
  });

  it("returns 0 for empty cart", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when subtotal equals freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 5000, 1)], 5000)).toBe(0);
  });

  it("returns 0 when subtotal exceeds freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 6000, 1)], 6000)).toBe(0);
  });

  it("returns flat fee when subtotal is below freeOverCents", () => {
    const calc = new FlatShippingCalculator(599, 5000);
    expect(calc.computeShippingCents([line("a", 4999, 1)], 4999)).toBe(599);
  });

  it("works without freeOverCents threshold", () => {
    const calc = new FlatShippingCalculator(599);
    expect(calc.computeShippingCents([line("a", 100000, 1)], 100000)).toBe(599);
  });

  it("accepts flatCents of 0", () => {
    const calc = new FlatShippingCalculator(0);
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
  });
});

describe("WeightBasedShippingCalculator", () => {
  it("rejects empty brackets", () => {
    expect(() => new WeightBasedShippingCalculator([])).toThrow(
      "at least one weight bracket is required",
    );
  });

  it("rejects non-positive upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 0, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: -1 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer upToGrams", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1.5, costCents: 100 }]),
    ).toThrow(RangeError);
  });

  it("rejects non-integer costCents", () => {
    expect(
      () => new WeightBasedShippingCalculator([{ upToGrams: 1000, costCents: 1.5 }]),
    ).toThrow(RangeError);
  });

  it("rejects negative overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          -1,
        ),
    ).toThrow(RangeError);
  });

  it("rejects non-integer overflowCostCents", () => {
    expect(
      () =>
        new WeightBasedShippingCalculator(
          [{ upToGrams: 1000, costCents: 100 }],
          5.5,
        ),
    ).toThrow(RangeError);
  });

  it("returns 0 for empty cart", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });

  it("returns 0 when total weight is 0 (no weightGrams set)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 1)], 100)).toBe(0);
  });

  it("selects the correct bracket", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 10000, costCents: 2000 },
    ]);
    // 800g → first bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 800)], 100)).toBe(500);
    // 3000g → second bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 3000)], 100)).toBe(1000);
    // 7000g → third bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 7000)], 100)).toBe(2000);
  });

  it("selects bracket at exact boundary (inclusive upper bound)", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);
    // exactly 1000g → first bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 1000)], 100)).toBe(500);
    // 1001g → second bracket
    expect(calc.computeShippingCents([line("a", 100, 1, 1001)], 100)).toBe(1000);
  });

  it("uses overflow cost when weight exceeds all brackets", () => {
    const calc = new WeightBasedShippingCalculator(
      [
        { upToGrams: 1000, costCents: 500 },
        { upToGrams: 5000, costCents: 1000 },
      ],
      3000,
    );
    expect(calc.computeShippingCents([line("a", 100, 1, 6000)], 100)).toBe(3000);
  });

  it("defaults overflow to last bracket cost", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);
    expect(calc.computeShippingCents([line("a", 100, 1, 6000)], 100)).toBe(1000);
  });

  it("sorts unsorted brackets correctly", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 5000, costCents: 1000 },
      { upToGrams: 1000, costCents: 500 },
    ]);
    // 800g should hit the 1000g bracket (500 cents) even though it was listed second
    expect(calc.computeShippingCents([line("a", 100, 1, 800)], 100)).toBe(500);
  });

  it("sums weight across multiple lines", () => {
    const calc = new WeightBasedShippingCalculator([
      { upToGrams: 1000, costCents: 500 },
      { upToGrams: 5000, costCents: 1000 },
    ]);
    const lines = [line("a", 100, 2, 400), line("b", 200, 3, 100)];
    // total weight = 800 + 300 = 1100 → second bracket
    expect(calc.computeShippingCents(lines, 300)).toBe(1000);
  });
});

